views.logistics=()=>title('TRAZABILIDAD / SALIDA Y RECEPCIÓN','Un folio. Cuatro puntos de control.','La central instruye movimientos del CEDIS y entre sucursales.')+intro()+`<div class="ops-explainer">${[['01 · Solicitar','Reserva disponibilidad del origen.'],['02 · Leer y surtir','El código debe coincidir con la referencia.'],['03 · Despachar','Descuenta el origen y deja saldo en tránsito.'],['04 · Conciliar','Suma sólo lo recibido. La diferencia sigue abierta.']].map(([h,p])=>`<div><b>${h}</b><p>${p}</p></div>`).join('')}</div><section class="panel"><h2>Instrucción central de traslado</h2><div class="ops-form">${field('Origen',`<select id="tr-source">${optsLocation(0)}</select>`)}${field('Destino',`<select id="tr-dest">${optsLocation(1)}</select>`)}${field('Referencia',`<select id="tr-product">${optsProduct(p=>p.active)}</select>`)}${field('Cantidad en la unidad del artículo','<input id="tr-qty" type="number" min="0.001" step="any" value="3">')}${field('Motivo / instrucción','<input id="tr-reason" placeholder="Reposición, apoyo entre tiendas, cliente clave…">')}${field('Crear solicitud','<button id="tr-create" class="full">Reservar con folio ↗</button>')}</div></section><section class="panel"><div class="row"><h2>Traslados · ${ops.orders.length}</h2><span class="micro">Código de demostración / sin lector conectado</span></div>${ops.orders.length?ops.orders.slice().reverse().map(orderHTML).join(''):'<div class="empty">Crea una solicitud. Usa el código visible de su producto para demostrar el surtido.</div>'}</section>`;
function orderHTML(t){let p=item(t.product);return `<article class="ops-order"><div class="row"><h3>${t.id} · ${loc(t.source)} → ${loc(t.dest)}</h3>${status(t.issue?'Diferencia abierta':['Solicitado','En surtido','En tránsito','Conciliado'][t.stage],t.issue?'issue':t.stage===3?'done':'')}</div><p>${esc(p.sku)} · ${esc(p.desc)} · ${esc(p.presentation)}<br>Solicitado ${fmt(t.qty)} / surtido ${fmt(t.picked)} / recibido ${fmt(t.received)} ${p.unit} · ${esc(t.reason)}</p><div class="timeline">${[0,1,2,3].map(i=>`<span class="${i<=t.stage?'on':''}"></span>`).join('')}</div>${t.issue?`<div class="ops-error">${esc(t.issue)}. La cantidad pendiente permanece en tránsito hasta aclarar su recepción; no se compensa con otro SKU.</div>`:''}${t.stage<2?`<div class="notice">Código del artículo: <b>${esc(p.barcode)}</b> · También puedes capturar ${esc(p.sku)}. Cada lectura de PZA suma una pieza por defecto.</div><div class="actions"><div><label>Código leído / capturado</label><input data-scan-code="${t.id}" style="width:190px" placeholder="PJM-DEMO-001"></div><div><label>Cantidad leída (${p.unit})</label><input data-scan-qty="${t.id}" type="number" step="any" min="0.001" value="1"></div><button class="secondary" data-scan="${t.id}">Registrar lectura</button></div><div class="actions"><input data-driver="${t.id}" style="width:190px" placeholder="Responsable de entrega"><button data-dispatch="${t.id}" ${t.qty!==t.picked?'disabled':''}>Confirmar salida</button></div>`:t.stage===2?`<div class="actions"><div><label>Recibir ahora (${p.unit})</label><input data-receive-qty="${t.id}" type="number" min="0.001" step="any" value="${round(t.qty-t.received)}"></div><input data-receiver="${t.id}" placeholder="Quién recibe"><input data-receive-note="${t.id}" style="width:190px" placeholder="Motivo si existe diferencia"><button data-receive="${t.id}">Confirmar recepción</button></div>`:''}<details><summary style="font-size:10px;color:#b49c7a">Historia del folio</summary><div class="event">${t.events.map(esc).join('<br>')}</div></details></article>`}
views.purchases=()=>title('ABASTECIMIENTO / ENTRADA AL CEDIS','Del proveedor a una entrada verificable.','Orden de compra, recepción parcial, pendientes, lote y caducidad declarada.')+intro()+`<section class="panel"><div class="row"><h2>Nueva orden de compra</h2><button id="new-product" class="secondary">+ Alta rápida de referencia</button></div><div class="ops-form">${field('Proveedor de ejemplo','<input id="po-supplier" placeholder="Proveedor demo">')}${field('Referencia',`<select id="po-product">${optsProduct(p=>p.active)}</select>`)}${field('Cantidad','<input id="po-qty" type="number" step="any" min="0.001" value="10">')}<div class="wide"><button id="po-create">Crear orden a CEDIS ↗</button></div></div></section><section class="panel"><h2>Compras y saldos pendientes</h2>${ops.purchases.length?ops.purchases.slice().reverse().map(p=>`<article class="ops-order"><div class="row"><h3>${p.id} · ${esc(p.supplier)}</h3>${status(p.received===p.qty?'Recibida':'Pendiente',p.received===p.qty?'done':'')}</div><p>${item(p.product).sku} · Pedido ${fmt(p.qty)} / recibido ${fmt(p.received)} / pendiente ${fmt(p.qty-p.received)} ${item(p.product).unit}</p>${p.received<p.qty?`<div class="actions"><div><label>Recibir ahora</label><input data-po-qty="${p.id}" type="number" min="0.001" step="any" value="${p.qty-p.received}"></div><div><label>Lote</label><input data-po-lot="${p.id}" placeholder="Lote demo"></div><div><label>Caducidad declarada</label><input data-po-exp="${p.id}" type="date" style="width:150px"></div><button data-po-receive="${p.id}">Registrar entrada</button></div>`:`<div class="event">Lote ${esc(p.lot)} · caducidad ${p.expiry}</div>`}</article>`).join(''):'<p>Las recepciones incrementan sólo el CEDIS. Los parciales conservan el pendiente de la misma orden.</p>'}</section>`;
views.production=()=>title('PRODUCCIÓN / IDENTIDAD Y BALANCE','Transformar sin perder el rastro.','Apertura por color, reenvasado central y remanentes identificados.')+intro()+`<div class="ops-tabs"><button data-ops-tab="envases" class="${opsTab==='envases'?'on':''}">Apertura por referencia</button><button data-ops-tab="reenvasado" class="${opsTab==='reenvasado'?'on':''}">Reenvasado central</button></div>${opsTab==='envases'?`<section class="panel"><div class="eyebrow">ENVASE CERRADO → LITROS CON IDENTIDAD</div><h2 class="editorial">El negro sigue siendo negro.</h2><p>La apertura descuenta envases y crea un saldo en litros ligado a SKU, color, sucursal y lote. No desaparece en una clave genérica.</p><div class="ops-form">${field('Ubicación',`<select id="open-location">${optsLocation(1)}</select>`)}${field('Referencia cerrada',`<select id="open-product">${optsProduct(p=>p.active&&p.litres)}</select>`)}${field('Número de envases','<input id="open-count" type="number" min="1" step="1" value="1">')}${field('Lote de origen','<input id="open-lot" placeholder="LOTE-DEMO">')}<div><label>Factor declarado</label><div id="open-factor" class="ops-detail">1 envase = 1 L para la primera referencia del ejemplo.</div></div><div><label>Confirmación</label><button id="open-create" class="full">Abrir y conservar identidad</button></div></div></section><section class="panel"><h2>Material abierto · trazabilidad por color</h2><div class="ops-scroll"><table><thead><tr><th>Folio</th><th>Sucursal / referencia</th><th>Lote</th><th>Apertura</th><th>Saldo identificado</th></tr></thead><tbody>${ops.opened.map(x=>`<tr><td>${x.id}</td><td>${loc(x.location)}<br>${item(x.product).sku} · ${item(x.product).desc}</td><td>${esc(x.lot)}</td><td>${fmt(x.initial)} L</td><td class="opened">${fmt(x.litres)} L</td></tr>`).join('')||'<tr><td colspan="5">Sin aperturas registradas.</td></tr>'}</tbody></table></div><div class="notice">Apertura y consumo son operaciones distintas. Esta edición demuestra apertura con identidad; la bitácora de igualación no descuenta bases sin receta y consumos autorizados.</div></section>`:`<section class="panel"><div class="eyebrow">PRODUCCIÓN CENTRALIZADA</div><h2 class="editorial">Lo que entra debe explicar lo que sale.</h2><p>Balance de materia: contenido en envases + merma declarada = consumo de materia prima. El remanente permanece disponible.</p><div class="ops-form">${field('Proceso de ejemplo',`<select id="pack-pair">${packPairs.map((p,i)=>`<option value="${i}">${p.label}</option>`).join('')}</select>`)}${field('Envases a producir','<input id="pack-count" type="number" min="1" step="1" value="4">')}${field('Merma en unidad de origen (kg o g)','<input id="pack-waste" type="number" min="0" step="any" value="0">')}${field('Lote de producción','<input id="pack-lot" placeholder="PROD-DEMO">')}<div class="wide"><div id="pack-preview" class="notice"></div><button id="pack-create">Registrar producción con balance</button></div></div></section><section class="panel"><h2>Órdenes de reenvasado</h2>${ops.packs.slice().reverse().map(p=>`<div class="activity"><div class="row"><b>${p.id} · lote ${esc(p.lot)}</b>${status('Balance registrado','done')}</div><p>${item(p.source).sku} → ${item(p.target).sku}<br>Consumo ${fmt(p.used)} ${p.unit} · merma ${fmt(p.waste)} ${p.unit} · ${p.count} envases · remanente ${fmt(p.remaining)} ${p.unit}</p></div>`).join('')||'<p>Los factores 250 g y 50 g son ejemplos del prototipo; requieren homologación por producto antes de operar.</p>'}</section>`}`;
views.equalizing=()=>title('BITÁCORA / IGUALACIÓN Y VENTA','El conocimiento del igualador, documentado.','Digitaliza el registro por sucursal, operador, marca, color e importe.')+intro()+`<div class="cards">${[['TRABAJOS REGISTRADOS',ops.jobs.length,'Registros de este navegador'],['VOLUMEN PRODUCIDO',fmt(ops.jobs.reduce((s,j)=>s+j.litres,0))+' L','No equivale automáticamente a venta'],['VOLUMEN CON VENTA CAPTURADA',fmt(ops.jobs.filter(j=>j.sold).reduce((s,j)=>s+j.litres,0))+' L','Pendiente de conciliación con POS'],['IMPORTE CAPTURADO','$'+fmt(ops.jobs.filter(j=>j.sold).reduce((s,j)=>s+j.amount,0)),'MXN · no es facturación fiscal']].map(x=>`<div class="card"><small>${x[0]}</small><div class="value">${x[1]}</div><small>${x[2]}</small></div>`).join('')}</div><section class="panel"><h2>Nuevo trabajo de igualación</h2><div class="ops-form">${field('Sucursal',`<select id="job-location">${optsLocation(1)}</select>`)}${field('Igualador / operador demo','<input id="job-operator" placeholder="Operador demo A">')}${field('Marca / sistema declarado','<input id="job-brand" placeholder="Sistema por validar">')}${field('Referencia / color solicitado','<input id="job-reference" placeholder="Clave, marca de auto, muestra…">')}${field('Litros producidos','<input id="job-litres" type="number" min="0.001" step="0.001" value="0.25">')}${field('Importe capturado (MXN)','<input id="job-amount" type="number" min="0" step="0.01" value="0">')}${field('Estado de venta','<select id="job-sold"><option value="0">Producción sin venta confirmada</option><option value="1">Venta capturada · pendiente de POS</option></select>')}${field('Ticket / referencia de venta','<input id="job-ticket" placeholder="Folio de ejemplo">')}<div><label>Guardar registro</label><button id="job-create" class="full">Registrar igualación</button></div></div><div class="notice">Conservamos el papel del igualador. Espectrofotómetro, receta, consumos por base y evidencia de probeta están pendientes de integración y validación. No prometemos igualación física desde RGB.</div></section><section class="panel"><h2>Bitácora de trabajos</h2><div class="ops-scroll"><table class="ops-table"><thead><tr><th>Folio / fecha</th><th>Sucursal / igualador</th><th>Marca / referencia</th><th>Producido</th><th>Venta capturada</th><th>Ticket</th></tr></thead><tbody>${ops.jobs.slice().reverse().map(j=>`<tr><td>${j.id}<small>${j.time}</small></td><td>${loc(j.location)}<small>${esc(j.operator)}</small></td><td>${esc(j.brand)}<small>${esc(j.reference)}</small></td><td>${fmt(j.litres)} L</td><td>${j.sold?'$'+fmt(j.amount)+' MXN':'Pendiente'}</td><td>${esc(j.ticket||'—')}</td></tr>`).join('')||'<tr><td colspan="6">Sin registros. Captura el primer trabajo.</td></tr>'}</tbody></table></div></section>`;
views.audit=()=>title('CONTROL / CONTEOS Y AUTORIZACIONES','Cada diferencia merece una explicación.','Sin ajustes silenciosos y sin compensar faltantes de un SKU con sobrantes de otro.')+intro()+`<section class="panel"><h2>Conteo físico / solicitud de ajuste</h2><div class="ops-form">${field('Ubicación',`<select id="count-location">${optsLocation(1)}</select>`)}${field('Referencia',`<select id="count-product">${optsProduct()}</select>`)}${field('Conteo físico en unidad del artículo','<input id="count-qty" type="number" min="0" step="any" value="0">')}${field('Motivo / evidencia declarada','<input id="count-reason" placeholder="Conteo cíclico, cierre, daño observado…">')}<div><label>Capturar</label><button id="count-create">Solicitar revisión</button></div></div><div class="notice">Registrar un conteo no altera inventario. Gerencia revisa y aprueba en el selector de rol demo. Si el saldo cambió o hay reservas incompatibles, el ajuste se bloquea.</div></section><section class="panel"><h2>Ajustes pendientes y resueltos</h2>${ops.counts.slice().reverse().map(c=>`<div class="activity"><div class="row"><b>${c.id} · ${loc(c.location)} · ${item(c.product).sku}</b>${status(c.status,c.status==='Aprobado'?'done':'issue')}</div><p>Sistema ${fmt(c.before)} / físico ${fmt(c.physical)} / diferencia ${fmt(c.physical-c.before)} ${item(c.product).unit}<br>${esc(c.reason)}</p>${c.status==='Pendiente'?`<button data-approve="${c.id}" class="secondary">Aprobar como Gerencia</button>`:''}</div>`).join('')||'<p>Sin solicitudes de ajuste.</p>'}</section><section class="panel"><h2>Cierre diario por sucursal</h2><p>El cierre captura revisión del responsable. Las diferencias por referencia se tramitan arriba, sin normalizar automáticamente saldos.</p><div class="ops-form">${field('Sucursal',`<select id="close-location">${optsLocation(1)}</select>`)}${field('Fecha operativa','<input id="close-date" type="date" value="2026-10-16">')}${field('Resultado declarado','<select id="close-result"><option>Con diferencias por revisar</option><option>Sin diferencias declaradas</option></select>')}${field('Comentario del responsable','<input id="close-note" placeholder="Folio de conteo, conciliación pendiente…">')}<div><label>Enviar a central</label><button id="close-create">Registrar cierre</button></div></div>${ops.closures.slice().reverse().map(c=>`<div class="activity"><b>${loc(c.location)} · ${c.date}</b><p>${esc(c.result)} · ${esc(c.note)} · ${c.time}</p></div>`).join('')}</section><section class="panel"><h2>Bitácora de movimientos · ${ops.events.length} eventos</h2><div class="ops-scroll"><table class="ops-table"><thead><tr><th>Fecha / usuario demo</th><th>Evento / folio</th><th>Detalle</th></tr></thead><tbody>${ops.events.map(e=>`<tr><td>${e.time}<small>${e.role}</small></td><td>${e.type}<small>${e.ref}</small></td><td>${esc(e.detail)}</td></tr>`).join('')||'<tr><td colspan="3">Sin eventos todavía.</td></tr>'}</tbody></table></div><div class="notice">Roles y bitácora son una demostración local, no seguridad productiva. Una implementación real requiere autenticación, permisos de servidor y registro protegido de auditoría.</div></section>`;
views.overview=()=>`<div class="page-fade"><div class="hero"><div class="hero-copy"><div class="eyebrow">PJM / OPERACIÓN CON TRAZABILIDAD</div><h1>La precisión<br><em>también se entrega.</em></h1><p>Del CEDIS a cada sucursal. Del envase cerrado al color igualado. Cada movimiento conserva su identidad.</p><div class="hero-actions"><button data-nav="logistics">Demostrar un traslado ↗</button><button class="secondary" data-nav="lab">Entrar al atelier</button></div></div><div class="hero-art"><div class="orb-ring"></div><div class="orb-ring"></div><div class="orb"></div><div class="art-caption"><span>EDICIÓN 03 / PJM<br><br>ADAPTADA AL LEVANTAMIENTO</span><span>16 OCTUBRE 2026<br><br>ESCENARIO FICTICIO</span></div></div></div><div class="cards">${[['RED OPERATIVA','11 + 1','Sucursales + PJM CEDIS'],['TRASLADOS ABIERTOS',ops.orders.filter(t=>t.stage<3).length,'Reservados, en surtido o en tránsito'],['DIFERENCIAS DE ENTREGA',ops.orders.filter(t=>t.issue).length,'Pendientes de recepción conciliada'],['REPOSICIONES ELEGIBLES',opsPlan().length,'Políticas de ejemplo por referencia']].map(x=>`<div class="card"><small>${x[0]}</small><div class="value">${x[1]}</div><small>${x[2]}</small></div>`).join('')}</div><div class="operations-side"><div class="panel ai-hub"><div class="row"><div class="eyebrow">✦ ASISTENCIA OPERATIVA</div><span class="pill demo">Motor por reglas</span></div><h2 class="editorial">La siguiente acción,<br>con evidencia.</h2><div class="insight"><b>${opsPlan().length} propuestas de reposición</b><p>Reviso el físico, entradas abiertas, reservas del CEDIS y la capacidad de exhibición. El aerosol del ejemplo tiene objetivo y capacidad de 5 piezas, no un mínimo genérico de gramos.</p></div><button data-ai="inventario">Revisar criterios y plan ↗</button><div class="ops-source">Datos ficticios actualizados por movimientos en este navegador. Sin ventas históricas, Power BI ni pronóstico conectado.</div></div><div class="panel"><h2>Lo que cambió con el levantamiento</h2><div class="activity"><b>01 / Integridad de la referencia</b><small>La apertura a litros conserva SKU, color y lote.</small></div><div class="activity"><b>02 / Salida y recepción hacen match</b><small>Picking por código y diferencias pendientes, sin sustituciones silenciosas.</small></div><div class="activity"><b>03 / Producción con balance</b><small>Contenido, merma y remanente de cada reenvasado.</small></div><button class="secondary" data-nav="findings" style="margin-top:15px">Ver adecuaciones y pendientes</button></div></div><section class="panel"><div class="row"><h2>Consulta por sucursal</h2><span class="micro">Mínimos declarados / escenario demo</span></div><div class="network-mini">${['PJM · CEDIS',...branches].map((b,d)=>`<button data-ops-branch="${d}"><span>${d?'SUC. '+String(d).padStart(2,'0'):'CEDIS'}</span><b>${d?ops.catalog.filter(p=>p.unit==='PZA'&&ops.balances[d][p.id]<p.min).length:'▦'}</b><span>${d?'bajo mínimo':'central'}</span></button>`).join('')}</div></section></div>`;
views.contact=()=>title('TELEMARKETING / VOZ DEL CLIENTE','Escuchar también es controlar la operación.','Casos de sucursales, clientes clave y subdistribuidores, ligados a folios.')+intro()+`<div class="operations-side"><section class="panel"><h2>Registrar caso</h2><div class="ops-form" style="grid-template-columns:1fr 1fr">${field('Canal','<select id="case-channel"><option>Sucursal</option><option>Cliente clave</option><option>Subdistribuidor</option></select>')}${field('Categoría','<select id="case-category"><option>Diferencia de entrega</option><option>Contenido de envase</option><option>Atención / igualación</option><option>Disponibilidad de producto</option></select>')}${field('Folio de traslado, producción o ticket','<input id="case-ref" placeholder="TR-PJM-0001, OP-0001…">',true)}${field('Descripción','<textarea id="case-note" placeholder="Necesidad o incidencia, sin datos personales reales"></textarea>',true)}<div class="wide"><button id="case-create">Abrir caso</button></div></div></section><section class="panel"><h2>Seguimiento de casos</h2>${ops.cases.slice().reverse().map(c=>`<div class="activity"><div class="row"><b>${c.id} · ${c.channel}</b>${status(c.closed?'Resuelto':'Abierto',c.closed?'done':'issue')}</div><p>${c.category} · ${esc(c.ref||'Sin folio vinculado')}<br>${esc(c.note)}</p>${!c.closed?`<div class="actions"><input data-case-resolution="${c.id}" placeholder="Cómo se resolvió"><button class="secondary" data-case-close="${c.id}">Resolver con nota</button></div>`:`<p>Resolución: ${esc(c.resolution)}</p>`}</div>`).join('')||'<p>Los casos se registran sólo en este navegador. No se envían mensajes al cliente.</p>'}</section></div>`;
const findings=[['Inventario comercial','Catálogo, marcas, líneas, unidades, presentaciones y matriz por sucursal. Se conservan nombres numerados hasta homologar las sucursales.','IMG_5075 · 7–146 s / IMG_5076 · 268–318 s'],['Picking y recepción','Solicitud central, lectura de código por texto, salida con responsable y recepción parcial. La diferencia queda abierta en tránsito.','IMG_5075 · 149–363 s / IMG_5083 · 0–104 s'],['Apertura con identidad','Envases cerrados a litros por factor declarado, preservando referencia, color, sucursal y lote. Sin litros genéricos que borren el SKU.','IMG_5076 · 373–517 s'],['Producción y reenvasado','Balance de materia prima, envases producidos, merma y remanente. Procesos separados en kg y g; sin convertir masa a volumen.','IMG_5079 · 47–155 s / IMG_5082 · 0–85 s y 302–386 s'],['Bitácora del igualador','Sucursal, operador demo, marca, referencia, litros, importe y ticket. Producción y venta capturada se muestran por separado.','IMG_5082 · 239–262 s y 428–453 s / hojas IMG_5083–85'],['Compra centralizada','Orden a proveedor, recepciones parciales y pendientes, lote y caducidad declarada. Alta rápida y bloqueo de descontinuados.','IMG_5076 · 153–231 s y 268–318 s'],['Conteos, cierres y auditoría','Sin editar directamente existencias: conteo → solicitud → aprobación de Gerencia. Registro del antes y después, motivo y rol demo.','IMG_5075 · 494–577 s / IMG_5076 · 0–109 s / IMG_5084 · 0–126 s'],['Reposición explicable','Políticas por referencia y capacidad de exhibición. Recomendación con existencias y entradas abiertas, sin afirmar predicción real.','IMG_5085 · 0–86 s']];
views.findings=()=>title('LEVANTAMIENTO / DISEÑO DE LA SOLUCIÓN','Lo observado se convierte en decisiones.','Revisión de siete videos y una fotografía. Resumen operativo, sin datos personales ni grabaciones en el sitio.')+`<section class="panel">${findings.map(([h,p,s],i)=>`<div class="proof"><span class="number">0${i+1}</span><div><h3>${h}</h3><p>${p}</p><div class="ops-source">${s} · transcripción automática sujeta a validación</div></div></div>`).join('')}</section><section class="panel"><h2>Lo que requiere verificación antes de implementar</h2><div class="ops-detail">Versión, licencias y mecanismo de integración de Aspel SAE e interfaz actual; exportación de catálogo y saldos; homologación de claves y códigos; nombres de sucursales; factores de presentación; lotes y caducidades; políticas de cierre, merma y autorización; lectores y equipos; espectrofotómetro, dosificadoras y protocolos; identidad y permisos reales; receta y consumos por base; conciliación con venta/facturación.</div><div class="notice">Se conserva el atelier como exploración RGB. No garantiza color físico, no reemplaza al igualador y no envía instrucciones a máquinas. La IA conversacional y el análisis predictivo reales continúan pendientes de integración. Todos los saldos e importes aquí son ficticios.</div><button id="reset-ops" class="secondary">Reiniciar sólo el escenario operativo</button></section>`;
views.demo=()=>title('GUION / REUNIÓN CON PJM','La demostración ahora sigue su operación.','Recorrido de 10 minutos adaptado al levantamiento del cliente.')+`<section class="panel">${[['1 min · Partir del problema real','“Hoy el producto puede cambiar entre lo pedido, surtido y recibido. Aquí seguimos la misma referencia y un solo folio.”','overview'],['2 min · Solicitar, escanear y despachar','Crea un traslado de 3 piezas. Copia su código visible y registra tres lecturas. La salida sólo se habilita al completar el surtido. Captura responsable.','logistics'],['1 min · Hacer visible la diferencia','Recibe 2 de las 3 piezas con una nota. La sucursal suma sólo 2 y queda 1 en tránsito. Recibe la pieza restante para conciliar.','logistics'],['1 min · Conservar el color al abrir','Abre una presentación cerrada con lote. Verifica su saldo en litros y que mantiene SKU, color y sucursal.','production'],['1 min · Producir con balance','En reenvasado, produce cuatro envases de 250 g desde granel en kg. Declara merma si aplica y revisa el remanente. Los factores son ejemplos.','production'],['1 min · Digitalizar la igualación','Registra sucursal, igualador, marca, litros, ticket e importe. Distingue lo producido de lo capturado como venta.','equalizing'],['1 min · Cerrar con control','Captura un conteo con diferencia. Cambia al rol Gerencia demo y aprueba; muestra el motivo y el antes/después en auditoría.','audit'],['2 min · Mantener la visión','Entra al atelier y explora una colección. Cierra revisando integración SAE, datos, hardware y reglas que se deben homologar. La cotización viene después del alcance validado.','lab']].map(([h,p,n],i)=>`<div class="proof"><span class="number">0${i+1}</span><div><h3>${h}</h3><p>${p}</p><button data-nav="${n}" class="secondary" style="margin-top:10px">Abrir escena ↗</button></div></div>`).join('')}</section>`;
function productModal(p){const x=item(p);openModal(`<div class="eyebrow">CATÁLOGO CENTRAL / DATOS DE EJEMPLO</div><h2>${esc(x.desc)}</h2><div class="spec-grid"><div class="spec"><small>CLAVE</small><b>${esc(x.sku)}</b></div><div class="spec"><small>CÓDIGO DEMO</small><b>${esc(x.barcode)}</b></div><div class="spec"><small>MARCA / LÍNEA</small><b>${esc(x.brand)} / ${esc(x.line)}</b></div><div class="spec"><small>PRESENTACIÓN / UNIDAD</small><b>${esc(x.presentation)} / ${x.unit}</b></div></div><p>Mínimo ${x.min} · objetivo ${x.target} · capacidad ${x.capacity} ${x.unit}. Políticas de ejemplo.</p><div class="notice">Descontinuar bloquea nuevas solicitudes y compras. Permite completar movimientos ya abiertos y consultar el histórico. No altera saldos ni elimina registros.</div><button id="toggle-active">${x.active?'Marcar descontinuado':'Reactivar referencia'}</button>`);document.querySelector('#toggle-active').onclick=()=>safeAction(()=>{central();x.active=!x.active;event('Estado de catálogo',x.sku,x.active?'Referencia reactivada':'Descontinuado: bloqueo de nuevas solicitudes y compras');document.querySelector('#modal-layer').remove();render();tell('Estado actualizado en toda la demo')})}
function newProductModal(){openModal(`<div class="eyebrow">ALTA RÁPIDA / COMPRA</div><h2>Crear referencia sin perder el contexto.</h2><div class="ops-form" style="grid-template-columns:1fr 1fr">${field('Clave DEMO única','<input id="np-sku" placeholder="DEMO-NUEVO01">')}${field('Descripción','<input id="np-desc" placeholder="Descripción del producto">')}${field('Marca','<input id="np-brand" placeholder="Marca declarada">')}${field('Línea','<input id="np-line" placeholder="Línea comercial">')}${field('Presentación','<input id="np-pack" placeholder="Presentación declarada">')}${field('Unidad','<select id="np-unit"><option>PZA</option><option>L</option><option>kg</option><option>g</option></select>')}<div class="wide"><button id="np-save">Crear referencia con saldo cero</button></div></div>`);document.querySelector('#np-save').onclick=()=>safeAction(()=>{central();const get=id=>document.querySelector(id).value.trim();let sku=get('#np-sku'),desc=get('#np-desc');need(sku.startsWith('DEMO-')&&sku.length>5,'Usa una clave única que comience con DEMO-.');need(!ops.catalog.some(p=>p.sku===sku),'La clave ya existe.');need(desc&&get('#np-brand')&&get('#np-line')&&get('#np-pack'),'Completa todos los campos.');const p={id:ops.catalog.length,sku,desc,brand:get('#np-brand'),line:get('#np-line'),presentation:get('#np-pack'),unit:get('#np-unit'),litres:null,barcode:'PJM-DEMO-'+String(ops.catalog.length+1).padStart(3,'0'),active:true,min:0,target:0,capacity:0};ops.catalog.push(p);ops.balances.forEach(b=>b.push(0));event('Alta de catálogo',sku,'Saldo inicial cero; sin factores de apertura supuestos');document.querySelector('#modal-layer').remove();render();tell('Referencia disponible para crear la compra')})}
function showOpsPlan(){const plan=opsPlan();openModal(`<div class="eyebrow">REPOSICIÓN / REVISIÓN CENTRAL</div><h2>${plan.length} movimientos propuestos</h2><p>Mínimo y objetivo por artículo, con capacidad máxima y entradas abiertas. No se suman cantidades de unidades incompatibles.</p><div class="ops-scroll"><table><thead><tr><th>Destino</th><th>Referencia</th><th>Proponer</th></tr></thead><tbody>${plan.map(t=>`<tr><td>${loc(t.dest)}</td><td>${item(t.product).sku}</td><td>${t.qty} ${item(t.product).unit}</td></tr>`).join('')}</tbody></table></div><div class="notice">Para el aerosol demo: mínimo 3, objetivo 5, capacidad 5 piezas. El plan se recalcula al confirmar y no duplica entradas abiertas.</div><button id="apply-ops-plan" ${!plan.length?'disabled':''}>Crear solicitudes de este plan</button>`);document.querySelector('#apply-ops-plan').onclick=()=>safeAction(()=>{central();let n=applyOpsPlan();document.querySelector('#modal-layer').remove();render();tell(n+' solicitudes creadas')})}
function applyOpsPlan(){central();let count=0;opsPlan().forEach(t=>{requestTransfer(t.source,t.dest,t.product,t.qty,'Reposición por política demo: mínimo, objetivo y capacidad');count++});return count}
function bindOps(){const value=id=>document.querySelector(id).value,number=id=>+value(id),on=(id,fn)=>{const e=document.querySelector(id);if(e)e.onclick=()=>safeAction(fn)},changed=(id,fn)=>{const e=document.querySelector(id);if(e)e.onchange=fn};document.querySelectorAll('[data-product]').forEach(b=>b.onclick=()=>productModal(+b.dataset.product));document.querySelectorAll('[data-ops-branch]').forEach(b=>b.onclick=()=>{opsLocation=+b.dataset.opsBranch;page='inventory';render()});
if(page==='inventory'){changed('#ops-location',e=>{opsLocation=+e.target.value;render()});changed('#ops-search',e=>{opsSearch=e.target.value;render()});on('#ops-matrix',()=>{opsMatrix=!opsMatrix;render()});on('#ops-plan',showOpsPlan)}
if(page==='logistics'){on('#tr-create',()=>{requestTransfer(number('#tr-source'),number('#tr-dest'),number('#tr-product'),number('#tr-qty'),value('#tr-reason'));render();tell('Solicitud reservada con folio')});document.querySelectorAll('[data-scan]').forEach(b=>b.onclick=()=>safeAction(()=>{scanTransfer(b.dataset.scan,value(`[data-scan-code="${b.dataset.scan}"]`),number(`[data-scan-qty="${b.dataset.scan}"]`));render();tell('Lectura registrada; referencia validada')}));document.querySelectorAll('[data-dispatch]').forEach(b=>b.onclick=()=>safeAction(()=>{dispatchTransfer(b.dataset.dispatch,value(`[data-driver="${b.dataset.dispatch}"]`));render();tell('Salida registrada; saldo en tránsito')}));document.querySelectorAll('[data-receive]').forEach(b=>b.onclick=()=>safeAction(()=>{receiveTransfer(b.dataset.receive,number(`[data-receive-qty="${b.dataset.receive}"]`),value(`[data-receiver="${b.dataset.receive}"]`),value(`[data-receive-note="${b.dataset.receive}"]`));render();tell('Recepción registrada con conciliación')}))}
if(page==='purchases'){on('#new-product',newProductModal);on('#po-create',()=>{makePurchase(number('#po-product'),number('#po-qty'),value('#po-supplier'));render();tell('Orden creada; destino CEDIS')});document.querySelectorAll('[data-po-receive]').forEach(b=>b.onclick=()=>safeAction(()=>{let id=b.dataset.poReceive;receivePurchase(id,number(`[data-po-qty="${id}"]`),value(`[data-po-lot="${id}"]`),value(`[data-po-exp="${id}"]`));render();tell('Entrada registrada; pendiente actualizado')}))}
if(page==='production'){document.querySelectorAll('[data-ops-tab]').forEach(b=>b.onclick=()=>{opsTab=b.dataset.opsTab;render()});const factor=()=>{const p=item(number('#open-product'));document.querySelector('#open-factor').textContent=`1 envase ${esc(p.sku)} = ${p.litres} L · factor de ejemplo por homologar.`};if(document.querySelector('#open-product')){factor();changed('#open-product',factor)}on('#open-create',()=>{openContainer(number('#open-location'),number('#open-product'),number('#open-count'),value('#open-lot'));render();tell('Apertura registrada; referencia y color conservados')});const preview=()=>{const p=packPairs[number('#pack-pair')],n=number('#pack-count'),w=number('#pack-waste');document.querySelector('#pack-preview').textContent=`${fmt(n*p.content+w)} ${p.unit} de materia prima = ${fmt(n*p.content)} ${p.unit} de contenido + ${fmt(w)} ${p.unit} de merma. Disponible: ${fmt(available(0,p.source))} ${p.unit}.`};if(document.querySelector('#pack-pair')){preview();['#pack-pair','#pack-count','#pack-waste'].forEach(id=>document.querySelector(id).oninput=preview)}on('#pack-create',()=>{packBatch(number('#pack-pair'),number('#pack-count'),number('#pack-waste'),value('#pack-lot'));render();tell('Producción registrada con balance y remanente')})}
if(page==='equalizing')on('#job-create',()=>{const sold=value('#job-sold')==='1';need(!sold||value('#job-ticket').trim(),'Una venta capturada requiere folio de ticket.');recordJob({location:number('#job-location'),operator:value('#job-operator'),brand:value('#job-brand'),reference:value('#job-reference'),litres:number('#job-litres'),amount:number('#job-amount'),sold,ticket:value('#job-ticket')});render();tell('Trabajo registrado; sin consumo de bases inferido')});
if(page==='audit'){on('#count-create',()=>{countStock(number('#count-location'),number('#count-product'),number('#count-qty'),value('#count-reason'));render();tell('Solicitud de ajuste enviada a revisión')});document.querySelectorAll('[data-approve]').forEach(b=>b.onclick=()=>safeAction(()=>{approveCount(b.dataset.approve);render();tell('Ajuste autorizado y auditado')}));on('#close-create',()=>{need(value('#close-date')&&value('#close-note').trim(),'Completa fecha y comentario del cierre.');const c={location:number('#close-location'),date:value('#close-date'),result:value('#close-result'),note:value('#close-note'),time:now()};need(!ops.closures.some(x=>x.location===c.location&&x.date===c.date),'Esta sucursal ya tiene un cierre para esa fecha.');ops.closures.push(c);event('Cierre diario declarado',loc(c.location),c.date+' · '+c.result+' · '+c.note);render();tell('Cierre registrado para revisión central')})}
if(page==='contact'){on('#case-create',()=>{need(value('#case-note').trim(),'Describe el caso.');const c={id:'CC-PJM-'+(ops.cases.length+1),channel:value('#case-channel'),category:value('#case-category'),ref:value('#case-ref'),note:value('#case-note'),closed:false};ops.cases.push(c);event('Caso de telemarketing',c.id,c.channel+' · '+c.category+' · '+c.ref);render();tell('Caso abierto')});document.querySelectorAll('[data-case-close]').forEach(b=>b.onclick=()=>safeAction(()=>{let c=ops.cases.find(c=>c.id===b.dataset.caseClose);const resolution=value(`[data-case-resolution="${c.id}"]`).trim();need(resolution,'Captura cómo se resolvió el caso.');c.closed=true;c.resolution=resolution;event('Caso resuelto',c.id,resolution);render();tell('Caso resuelto con nota')}))}
if(page==='findings')on('#reset-ops',()=>{ops=opsSeed();saveOps();aiMessages=[];render();tell('Escenario operativo reiniciado. Atelier y colecciones conservados.')})}
const creativeAIResponse=aiResponse;
aiResponse=function(q){const t=q.toLowerCase();if(/ver plan/.test(t)){const plan=opsPlan();return `<b>${plan.length} propuestas revisables por referencia.</b><div class="evidence">${plan.slice(0,6).map(x=>`${loc(x.dest)} · ${item(x.product).sku} · ${x.qty} ${item(x.product).unit}`).join('<br>')||'No hay reposiciones elegibles.'}<br>No se suman piezas y litros. Se recalcula al confirmar.</div>${plan.length?'<button data-action="ops-plan">Abrir plan completo</button>':'<button data-action="ops-logistics">Ver traslados abiertos</button>'}`}if(/invent|falt|repos|reabas|prior/.test(t)){let plan=opsPlan(),issues=ops.orders.filter(x=>x.issue).length;return `<b>${plan.length} reposiciones elegibles y ${issues} diferencias de entrega abiertas.</b><br>Uso políticas por referencia, capacidad, disponibilidad del CEDIS y entradas pendientes. No un mínimo genérico de gramos.<div class="evidence">Ejemplo aerosol: mínimo 3 / objetivo 5 / capacidad 5 piezas.<br>Fuente: ${ops.catalog.length} referencias ficticias × 12 ubicaciones; movimientos de este navegador.<br>Sin conexión a ventas históricas, Power BI ni SAE.</div><div class="ai-quick"><button data-ask="ver plan">Revisar plan</button><button data-action="ops-inventory">Abrir inventario</button></div>`}if(/logíst|logist|entrega|traslado|traspas/.test(t)){let pending=ops.orders.filter(t=>t.stage===2).length,issues=ops.orders.filter(t=>t.issue).length;return `<b>${pending} traslados en tránsito. ${issues} con diferencia abierta.</b><br>El origen se descuenta al despachar. El destino suma sólo lo que confirma recibir; el pendiente sigue en tránsito.<div class="evidence">Código por referencia, responsable de salida y receptor, historial por folio. No hay lector, GPS ni hardware conectado.</div><button data-action="ops-logistics">Revisar folios ↗</button>`}if(/igualador|bitácora|bitacora|litros|cierre|auditor|merma|produc|envasa|apertura/.test(t)){return `<b>Conservar identidad y explicar las diferencias.</b><br>El levantamiento mostró pérdida de referencia al convertir a litros y registros manuales. Ahora puedes abrir envases con SKU y lote, reenvasar con balance y capturar trabajos del igualador.<div class="evidence">${ops.opened.length} aperturas · ${ops.packs.length} órdenes de reenvasado · ${ops.jobs.length} trabajos · ${ops.counts.filter(x=>x.status==='Pendiente').length} ajustes por revisar.<br>Los conteos no corrigen el inventario hasta aprobación de Gerencia demo.</div><div class="ai-quick"><button data-action="ops-production">Abrir producción</button><button data-action="ops-audit">Ver control y cierres</button></div>`}return creativeAIResponse(q)};
drawAI=function(){const box=document.querySelector('#ai-body');if(!box)return;box.innerHTML=`<div class="ai-message"><b>Decisiones con contexto PJM.</b><br>Revisa reposición, diferencias de entrega, apertura de pintura o producción. Las recomendaciones usan datos ficticios y reglas explícitas.<div class="ai-quick"><button data-ask="inventario">Reposición</button><button data-ask="traslados">Entregas</button><button data-ask="producción">Producción</button><button data-ask="temporada">Colecciones</button></div></div>`+aiMessages.map(m=>`<div class="ai-message user">${esc(m.user)}</div><div class="ai-message">${m.answer}</div>`).join('');box.querySelectorAll('[data-ask]').forEach(b=>b.onclick=()=>askAI(b.dataset.ask));box.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>safeAction(()=>{const a=b.dataset.action;document.querySelector('#ai-panel').remove();if(a==='ops-plan'){showOpsPlan();return}page={'ops-logistics':'logistics','ops-inventory':'inventory','ops-production':'production','ops-audit':'audit','open-logistics':'logistics','open-lab':'lab','open-collection':'lab'}[a]||'lab';render();if(a==='open-collection')document.querySelector('#collection').scrollIntoView({behavior:'smooth',block:'center'})}));box.scrollTop=box.scrollHeight};
render=function(){document.querySelector('#nav').innerHTML=navs.map(([id,icon,label])=>`<button data-nav="${id}" class="${page===id?'active':''}">${icon} &nbsp; ${label}</button>`).join('');document.querySelector('#app').innerHTML=views[page]();document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{page=b.dataset.nav;render();window.scrollTo({top:0})});document.querySelectorAll('[data-ai]').forEach(b=>b.onclick=()=>openAI(b.dataset.ai));if(page==='lab')bindLab();else bindOps();if(!document.querySelector('#ai-trigger')){let b=document.createElement('button');b.id='ai-trigger';b.className='ai-trigger';b.innerHTML='<span class="ai-symbol">✦</span> JM Intelligence <span style="font-size:8px;opacity:.6">DEMO</span>';b.onclick=()=>openAI();document.body.appendChild(b)}document.querySelector('#app').classList.remove('page-fade');void document.querySelector('#app').offsetWidth;document.querySelector('#app').classList.add('page-fade')};
/* BOOTSTRAP OPERATIONS */
navs.splice(0,navs.length,['overview','◫','Centro de operación'],['inventory','▦','Inventario comercial'],['logistics','⇄','Surtido y traslados'],['purchases','↙','Compras y recepción'],['production','◈','Apertura y reenvasado'],['equalizing','≋','Bitácora de igualación'],['lab','◉','Atelier de color'],['contact','☏','Telemarketing'],['audit','◎','Control y cierres'],['findings','◇','Levantamiento'],['demo','▷','Guion de reunión']);
document.querySelector('aside footer').innerHTML='<span style="color:#cbb58f;font-size:13px;letter-spacing:1px">SyborX STUDIO</span><br>Edición 03 / Operación PJM<br><span style="font-size:9px;color:#657487">Escenario local de demostración</span>';
document.querySelector('header').innerHTML='<span class="header-title">PINTURAS JM <span style="color:#526174;margin:0 10px">/</span> OPERACIÓN PJM</span><div class="top-right"><span class="pill demo">Escenario ficticio · 16 oct</span><select id="ops-role" class="role-select" aria-label="Rol de demostración"><option>Central</option><option>Gerencia</option><option>Sucursal</option></select></div>';document.querySelector('#ops-role').onchange=e=>{opsRole=e.target.value;tell('Rol demo: '+opsRole+'. No equivale a autenticación real.')};render();
